import{_ as l,a0 as p,w as r,s as o,I as a,x as s,a1 as n,A as t,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"如何在 RHEL 8 上安裝 FreeIPA 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 RHEL 8 上安裝 FreeIPA 服務器 | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 RHEL 8 上安裝 FreeIPA 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 RHEL 8 上安裝 FreeIPA 服務器 | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230415.0 ⭐️⭐️ How to Install FreeIPA Server on RHEL 8  Rocky Linux 8  AlmaLinux 8","title":"如何在 RHEL 8 上安裝 FreeIPA 服務器","tag":"202305","desc":""},"relativePath":"202305/20230415.0 ⭐️⭐️ How to Install FreeIPA Server on RHEL 8  Rocky Linux 8  AlmaLinux 8.md","filePath":"[post].md"}'),h={name:"202305/20230415.0 ⭐️⭐️ How to Install FreeIPA Server on RHEL 8  Rocky Linux 8  AlmaLinux 8.md"};function c(u,e,g,k,b,m){const i=p("Link");return r(),o("div",null,[e[17]||(e[17]=a("h1",{id:"如何在-rhel-8-上安裝-freeipa-服務器",tabindex:"-1"},[s("如何在 RHEL 8 上安裝 FreeIPA 服務器 "),a("a",{class:"header-anchor",href:"#如何在-rhel-8-上安裝-freeipa-服務器","aria-label":"Permalink to “如何在 RHEL 8 上安裝 FreeIPA 服務器”"},"​")],-1)),e[18]||(e[18]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202305/05/160246m3vu7phhy7eyuo7j.png",alt:""})],-1)),e[19]||(e[19]=a("p",null,"你是否正在尋找有關如何在 Linux 上安裝 FreeIPA 服務器的簡單指南？",-1)),e[20]||(e[20]=a("p",null,"此頁面上的分步指南將展示如何在 RHEL 8、Rocky Linux 8 和 AlmaLinux 8 上安裝 FreeIPA 服務器。",-1)),a("p",null,[n(i,{href:"https://www.freeipa.org/page/Main_Page"},{default:t(()=>[...e[0]||(e[0]=[s("FreeIPA",-1)])]),_:1}),e[1]||(e[1]=s(" 是一個自由開源的基於 Linux 系統的集中式身份和訪問管理工具，它是 Red Hat 身份管理器的上游項目。使用 FreeIPA，我們可以輕鬆地管理集中式身份驗證以及帳户管理、策略（基於主機的訪問控制）和審計。",-1))]),e[21]||(e[21]=d(`<p>FreeIPA 基於以下開源項目：</p><ul><li>LDAP 服務器 – 基於 389 項目</li><li>KDC – 基於 MIT Kerberos 實現</li><li>基於 Dogtag 項目的 PKI</li><li>用於活動目錄集成的 Samba 庫</li><li>基於 BIND 和 Bind-DynDB-LDAP 插件的 DNS 服務器</li><li>NTP</li></ul><h3 id="先決條件" tabindex="-1">先決條件 <a class="header-anchor" href="#先決條件" aria-label="Permalink to “先決條件”">​</a></h3><ul><li>預裝 RHEL 8 或 Rocky Linux 8 或 AlmaLinux 8</li><li>具有管理員權限的 Sudo 用户</li><li>內存 = 2 GB</li><li>CPU = 2 個 vCPU</li><li>磁盤 = 根目錄有 12GB 可用空間</li><li>互聯網連接</li></ul><h3 id="freeipa-的實驗室詳細信息" tabindex="-1">FreeIPA 的實驗室詳細信息 <a class="header-anchor" href="#freeipa-的實驗室詳細信息" aria-label="Permalink to “FreeIPA 的實驗室詳細信息”">​</a></h3><ul><li>IP 地址 = 192.168.1.102</li><li>Hostanme = ipa.linuxtechi.lan</li><li>操作系統：RHEL 8 或 Rocky Linux 8 或 AlmaLinux 8</li></ul><p>事不宜遲，讓我們深入瞭解 FreeIPA 安裝步驟。</p><h3 id="_1、設置主機名並安裝更新" tabindex="-1">1、設置主機名並安裝更新 <a class="header-anchor" href="#_1、設置主機名並安裝更新" aria-label="Permalink to “1、設置主機名並安裝更新”">​</a></h3><p>打開服務器的終端並使用 <code>hostnamectl</code> 命令設置主機名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo hostnamectl set-hostname &quot;ipa.linuxtechi.lan&quot;</span></span>
<span class="line"><span>$ exec bash</span></span></code></pre></div><p>使用 <code>yum</code>/<code>dnf</code> 命令安裝更新，然後重新啓動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf update -y</span></span>
<span class="line"><span>$ sudo reboot</span></span></code></pre></div><h3 id="_2、更新主機文件並將-selinux-設置為許可" tabindex="-1">2、更新主機文件並將 SELinux 設置為許可 <a class="header-anchor" href="#_2、更新主機文件並將-selinux-設置為許可" aria-label="Permalink to “2、更新主機文件並將 SELinux 設置為許可”">​</a></h3><p>運行以下 <code>tee</code> 命令更新 <code>/etc/hosts</code> 文件，根據你的設置替換 IP 地址和主機名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo -e &quot;192.168.1.102\\tipa.linuxtechi.lan\\t ipa&quot; | sudo tee -a /etc/hosts</span></span></code></pre></div><p>將 SELinux 設置為許可，運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo setenforce 0</span></span>
<span class="line"><span>$ sudo sed -i &#39;s/^SELINUX=.*/SELINUX=permissive/g&#39; /etc/selinux/config</span></span>
<span class="line"><span>$ getenforce</span></span>
<span class="line"><span>Permissive</span></span></code></pre></div><h3 id="_3、安裝-freeipa-及其組件" tabindex="-1">3、安裝 FreeIPA 及其組件 <a class="header-anchor" href="#_3、安裝-freeipa-及其組件" aria-label="Permalink to “3、安裝 FreeIPA 及其組件”">​</a></h3><p>Appstream 包倉庫中提供了 FreeIPA 包及其依賴項。由於我們計劃安裝集成 DNS 的 FreeIPA，因此我們還將安裝 <code>ipa-server-dns</code> 和 <code>bind-dyndb-ldap</code>。</p><p>運行以下命令安裝 FreeIPA 及其依賴項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf -y install @idm:DL1</span></span>
<span class="line"><span>$ sudo dnf install freeipa-server ipa-server-dns bind-dyndb-ldap -y</span></span></code></pre></div><h3 id="_4、開始安裝-freeipa" tabindex="-1">4、開始安裝 FreeIPA <a class="header-anchor" href="#_4、開始安裝-freeipa" aria-label="Permalink to “4、開始安裝 FreeIPA”">​</a></h3><p>成功安裝 FreeIPA 包及其依賴項後，使用以下命令啓動 FreeIPA 安裝設置。</p><p>它將提示幾件事，例如配置集成 DNS、主機名、域名和領域名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ipa-server-install</span></span></code></pre></div><p>上述命令的輸出如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/11/IPA-Server-Install-Command-RHEL-RockyLinux-AlmaLinux.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/11/IPA-Install-Directory-Manager-IPA-Admin-Password.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>在上面的窗口中輸入 “yes” 後，需要一些時間來配置你的 FreeIPA 服務器，設置成功後，我們將得到下面的輸出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/11/IPA-Installation-Successful-Message-RHEL-AlmaLinux-RockyLinux.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>以上輸出確認 FreeIPA 已成功安裝。</p><h3 id="_5、在防火牆中允許-freeipa-端口" tabindex="-1">5、在防火牆中允許 FreeIPA 端口 <a class="header-anchor" href="#_5、在防火牆中允許-freeipa-端口" aria-label="Permalink to “5、在防火牆中允許 FreeIPA 端口”">​</a></h3><p>如果正在你的服務器上運行系統防火牆，那麼運行如下 <code>firewall-cmd</code> 命令以允許 FreeIPA 端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --add-service={http,https,dns,ntp,freeipa-ldap,freeipa-ldaps} --permanent</span></span>
<span class="line"><span>$ sudo firewall-cmd --reload</span></span></code></pre></div><h3 id="_6、訪問-freeipa-管理門户" tabindex="-1">6、訪問 FreeIPA 管理門户 <a class="header-anchor" href="#_6、訪問-freeipa-管理門户" aria-label="Permalink to “6、訪問 FreeIPA 管理門户”">​</a></h3><p>執行下面的 <code>ipactl</code> 命令查看 FreeIPA 的所有服務是否都在運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ipactl status</span></span>
<span class="line"><span>You must be root to run ipactl.</span></span>
<span class="line"><span>$ sudo ipactl status</span></span>
<span class="line"><span>Directory Service: RUNNING</span></span>
<span class="line"><span>krb5kdc Service: RUNNING</span></span>
<span class="line"><span>kadmin Service: RUNNING</span></span>
<span class="line"><span>named Service: RUNNING</span></span>
<span class="line"><span>httpd Service: RUNNING</span></span>
<span class="line"><span>ipa-custodia Service: RUNNING</span></span>
<span class="line"><span>pki-tomcatd Service: RUNNING</span></span>
<span class="line"><span>ipa-otpd Service: RUNNING</span></span>
<span class="line"><span>ipa-dnskeysyncd Service: RUNNING</span></span>
<span class="line"><span>ipa: INFO: The ipactl command was successful</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>讓我們使用 <code>kinit</code> 命令驗證管理員用户是否會通過 Kerberos 獲取令牌，使用我們在 FreeIPA 安裝期間提供的相同管理員用户密碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kinit admin</span></span>
<span class="line"><span>$ klist</span></span></code></pre></div><p>以上命令的輸出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/11/FeeIPA-kinit-admin-token.png" alt=""></p><p>完美，上面的輸出確認管理員獲得了令牌。現在，嘗試訪問 FreeIPA Web 控制台，在網絡瀏覽器上輸入以下 URL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://ipa.linuxtechi.lan/ipa/ui</span></span></code></pre></div><p>或者</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://&lt;Server-IPAddress&gt;/ipa/ui</span></span></code></pre></div><p>使用我們在安裝過程中指定的用户名 <code>admin</code> 和密碼。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/11/Accept-Risk-FreeIPA-WebConsole-URL-1024x556.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>對於 FreeIPA Web 控制台，使用自簽名 SSL 證書，這就是我們看到此窗口的原因，因此單擊“<ruby>接受風險並繼續<rt>Accept the Risk and Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/11/FreeIPA-Login-Page-RHEL-RockyLinux-AlmaLinux-1024x586.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>輸入憑據後，單擊“<ruby>登錄<rt>Log in</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/11/FreeIPA-Dashboard-RHEL-RockyLinux-AlmaLinux-1024x585.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>這證實我們已在 RHEL 8/Rocky Linux 8 / AlmaLinux8 上成功設置 FreeIPA。</p><p>這就是全部，我希望你覺得它提供了很多信息。請在下面的評論部分中發表你的疑問和反饋。</p><p><em>（題圖：MJ/9df57ea0-b5a0-48f9-a323-853a28ca6162）</em></p><hr>`,55)),a("p",null,[e[3]||(e[3]=s("via: ",-1)),n(i,{href:"https://www.linuxtechi.com/install-freeipa-rhel-rocky-almalinux/"},{default:t(()=>[...e[2]||(e[2]=[s("https://www.linuxtechi.com/install-freeipa-rhel-rocky-almalinux/",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=s("作者：",-1)),n(i,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...e[4]||(e[4]=[s("Pradeep Kumar",-1)])]),_:1}),e[9]||(e[9]=s(" 選題：",-1)),n(i,{href:"https://github.com/lkxed/"},{default:t(()=>[...e[5]||(e[5]=[s("lkxed",-1)])]),_:1}),e[10]||(e[10]=s(" 譯者：",-1)),n(i,{href:"https://github.com/geekpi"},{default:t(()=>[...e[6]||(e[6]=[s("geekpi",-1)])]),_:1}),e[11]||(e[11]=s(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[7]||(e[7]=[s("wxy",-1)])]),_:1})]),a("p",null,[e[14]||(e[14]=s("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[12]||(e[12]=[s("LCTT",-1)])]),_:1}),e[15]||(e[15]=s(" 原創編譯，",-1)),n(i,{href:"https://linux.cn/"},{default:t(()=>[...e[13]||(e[13]=[s("Linux中國",-1)])]),_:1}),e[16]||(e[16]=s(" 榮譽推出",-1))])])}const P=l(h,[["render",c]]);export{I as __pageData,P as default};
